class AllDistinctDoubleArraySamples {

    @Sample
    fun allDistinct() {
        assertTrue(doubleArrayOf().allDistinct())
        assertTrue(doubleArrayOf(1.0).allDistinct())

        val distinctValues = doubleArrayOf(1.0, 2.0, 3.0)
